namespace allmight {

void check(bool condition, const char* failure) {
    if (!condition) throw std::runtime_error(failure); // active with -DNDEBUG
}

struct AssetHandle {
    std::uint32_t slot;
    std::uint64_t generation;
    friend bool operator==(AssetHandle, AssetHandle) = default;
};

enum class AssetKind { Mesh, Texture, Shader };
struct AssetRecord {
    AssetHandle id;
    std::string name; // owned; snapshots never borrow ephemeral file paths
    std::size_t bytes;
    int priority;
    AssetKind kind;
};

// A minimal snapshot of the earlier generation-checked registry. It is owned
// and detached from the live registry; handles in it may become stale later.
std::vector<AssetRecord> example_snapshot() {
    return {
        {{0, 1}, "brick.mesh", 48, 2, AssetKind::Mesh},
        {{1, 1}, "sky.tex", 64, 3, AssetKind::Texture},
        {{2, 1}, "ui.tex", 16, 3, AssetKind::Texture},
        {{3, 2}, "terrain.mesh", 128, 1, AssetKind::Mesh},
        {{4, 1}, "rock.mesh", 48, 2, AssetKind::Mesh},
    };
}

// Presence/absence answers a question with no meaningful failure reason.
std::optional<AssetHandle> find_optional(
    const std::vector<AssetRecord>& assets, std::string_view name) {
    const auto it = std::find_if(assets.begin(), assets.end(),
        [name](const AssetRecord& asset) { return asset.name == name; });
    if (it == assets.end()) return std::nullopt;
    return it->id; // value, not a reference into the snapshot
}

// Different error conditions need a typed result, not a magic sentinel ID.
enum class LookupError { EmptyName, NotFound };
template <class E> struct Unexpected { E error; };

template <class T, class E>
class ExpectedLike {
    std::variant<T, Unexpected<E>> state_;
    explicit ExpectedLike(T value) : state_(std::move(value)) {}
    explicit ExpectedLike(Unexpected<E> failed) : state_(failed) {}
public:
    static ExpectedLike success(T value) { return ExpectedLike(std::move(value)); }
    static ExpectedLike failure(E error) {
        return ExpectedLike(Unexpected<E>{error});
    }
    bool has_value() const noexcept { return std::holds_alternative<T>(state_); }
    const T& value() const { return std::get<T>(state_); }
    const E& error() const { return std::get<Unexpected<E>>(state_).error; }
};

ExpectedLike<AssetHandle, LookupError> lookup(
    const std::vector<AssetRecord>& assets, std::string_view name) {
    if (name.empty()) return ExpectedLike<AssetHandle, LookupError>::failure(
        LookupError::EmptyName);
    auto candidate = find_optional(assets, name);
    if (!candidate) return ExpectedLike<AssetHandle, LookupError>::failure(
        LookupError::NotFound);
    return ExpectedLike<AssetHandle, LookupError>::success(*candidate);
}

// A closed set of commands is expressed with std::variant and std::visit.
struct Inspect { AssetHandle id; };
struct Upload { AssetHandle id; };
struct Evict { AssetHandle id; };
using AssetCommand = std::variant<Inspect, Upload, Evict>;

template <class... Functions> struct Overloaded : Functions... {
    using Functions::operator()...;
};
template <class... Functions> Overloaded(Functions...) -> Overloaded<Functions...>;

// A comparator with both argument orders supports lower_bound, upper_bound
// and equal_range on a vector sorted by byte count. Their precondition is a
// properly partitioned/sorted range under the SAME ordering relation.
struct CompareBytes {
    bool operator()(const AssetRecord& asset, std::size_t n) const noexcept {
        return asset.bytes < n;
    }
    bool operator()(std::size_t n, const AssetRecord& asset) const noexcept {
        return n < asset.bytes;
    }
};

void run() {
    auto assets = example_snapshot();
    check(assets.size() == 5, "owned snapshot retains five assets");

    // 251: Optional means 'may be missing' but does not encode why.
    const auto present = find_optional(assets, "rock.mesh");
    const auto absent = find_optional(assets, "missing.tex");
    check(present && *present == AssetHandle{4, 1} && !absent,
          "optional presence/absence is explicit");

    // 254: C++20 expected-like result is a deliberately small teaching type.
    const auto good = lookup(assets, "rock.mesh");
    const auto blank = lookup(assets, "");
    const auto missing = lookup(assets, "other.mesh");
    check(good.has_value() && good.value() == AssetHandle{4, 1},
          "expected-like success carries an ID");
    check(!blank.has_value() && blank.error() == LookupError::EmptyName &&
          !missing.has_value() && missing.error() == LookupError::NotFound,
          "expected-like failure preserves error cause");

    // 252: A visitor must handle each of the closed command alternatives.
    std::vector<AssetCommand> commands{Inspect{{0, 1}}, Upload{{1, 1}}, Evict{{2, 1}}};
    std::size_t inspect_count = 0, upload_count = 0, evict_count = 0;
    for (const AssetCommand& command : commands) {
        std::visit(Overloaded{
            [&](const Inspect& op) { check(op.id.slot == 0, "inspect ID"); ++inspect_count; },
            [&](const Upload& op) { check(op.id.slot == 1, "upload ID"); ++upload_count; },
            [&](const Evict& op) { check(op.id.slot == 2, "evict ID"); ++evict_count; },
        }, command);
    }
    check(inspect_count == 1 && upload_count == 1 && evict_count == 1,
          "visit dispatches by active type rather than casted bytes");

    // 253: An open-ended diagnostics channel can accept std::any. Wrong-type
    // access throws; any_cast does not magically convert string to integer.
    std::any diagnostic = std::string("texture-rgba");
    check(std::any_cast<const std::string&>(diagnostic) == "texture-rgba",
          "any stores an owned concrete value");
    bool wrong_type = false;
    try { (void)std::any_cast<int>(diagnostic); }
    catch (const std::bad_any_cast&) { wrong_type = true; }
    check(wrong_type, "bad_any_cast is detectable");
    diagnostic.reset();
    check(!diagnostic.has_value(), "empty std::any owns no target");

    // 255-256: A pair is two values; a tuple allows an arbitrary fixed set of
    // heterogeneous fields. Structured bindings copy with 'auto', and bind
    // to the original pair members with 'auto&'.
    std::pair<std::size_t, std::size_t> counts{assets.size(), 0};
    auto [copied_count, copied_errors] = counts;
    auto& [live_count, live_errors] = counts;
    ++live_errors;
    check(copied_count == 5 && copied_errors == 0 &&
          live_count == 5 && counts.second == 1,
          "structured bindings distinguish copies from aliases");
    const auto report = std::tuple{std::string("frame-assets"), assets.size(), 1u};
    const auto& [report_name, report_count, report_version] = report;
    check(report_name == "frame-assets" && report_count == 5 && report_version == 1,
          "tuple exposes fixed typed fields");

    // 257-258: iterator categories are compile-time capabilities; a deque
    // has random-access iterators but NOT contiguous element storage.
    static_assert(std::contiguous_iterator<std::vector<int>::iterator>);
    static_assert(std::random_access_iterator<std::deque<int>::iterator>);
    static_assert(!std::contiguous_iterator<std::deque<int>::iterator>);
    static_assert(std::bidirectional_iterator<std::list<int>::iterator>);
    static_assert(!std::random_access_iterator<std::list<int>::iterator>);
    static_assert(std::forward_iterator<std::forward_list<int>::iterator>);
    static_assert(!std::bidirectional_iterator<std::forward_list<int>::iterator>);
    static_assert(std::input_iterator<std::istream_iterator<int>>);
    static_assert(!std::forward_iterator<std::istream_iterator<int>>);
    std::istringstream input{"7 8 9"};
    std::vector<int> parsed{std::istream_iterator<int>{input}, std::istream_iterator<int>{}};
    check(parsed == std::vector<int>({7, 8, 9}), "input iterator consumes stream once");

    // 260: Sorting is not required to preserve equal-key input order.
    auto sorted = assets; // own a separate snapshot before rearranging
    std::sort(sorted.begin(), sorted.end(), [](const AssetRecord& a, const AssetRecord& b) {
        if (a.bytes != b.bytes) return a.bytes < b.bytes;
        return a.name < b.name; // deterministic tie break, not relied on stability
    });
    check(sorted.front().name == "ui.tex" && sorted.back().name == "terrain.mesh",
          "sort orders by bytes with explicit tie break");

    // 261: Stable sort DOES preserve original order for equivalent priorities.
    auto stable = assets;
    std::stable_sort(stable.begin(), stable.end(), [](const AssetRecord& a, const AssetRecord& b) {
        return a.priority > b.priority;
    });
    check(stable[0].name == "sky.tex" && stable[1].name == "ui.tex" &&
          stable[2].name == "brick.mesh" && stable[3].name == "rock.mesh",
          "stable_sort preserves equal-priority relative order");

    // 262: Partition divides two groups but does not sort either group or
    // guarantee the original relative order inside the groups.
    auto partitioned = assets;
    const auto dividing = std::partition(partitioned.begin(), partitioned.end(),
        [](const AssetRecord& a) { return a.kind == AssetKind::Mesh; });
    check(std::all_of(partitioned.begin(), dividing,
            [](const AssetRecord& a) { return a.kind == AssetKind::Mesh; }) &&
          std::none_of(dividing, partitioned.end(),
            [](const AssetRecord& a) { return a.kind == AssetKind::Mesh; }),
          "partition places predicate-true records first");
    check(std::partition_point(partitioned.begin(), partitioned.end(),
          [](const AssetRecord& a) { return a.kind == AssetKind::Mesh; }) == dividing,
          "partition_point requires already partitioned input");

    // 263-264: binary search requires the appropriate sorted/partitioned
    // order. Find both limits of the byte-size==48 subrange.
    std::sort(sorted.begin(), sorted.end(), [](const AssetRecord& a, const AssetRecord& b) {
        return a.bytes < b.bytes;
    });
    const auto lower = std::lower_bound(sorted.begin(), sorted.end(), std::size_t{48}, CompareBytes{});
    const auto upper = std::upper_bound(sorted.begin(), sorted.end(), std::size_t{48}, CompareBytes{});
    const auto both = std::equal_range(sorted.begin(), sorted.end(), std::size_t{48}, CompareBytes{});
    check(std::distance(sorted.begin(), lower) == 1 &&
          std::distance(sorted.begin(), upper) == 3 &&
          both.first == lower && both.second == upper,
          "binary-search contract finds exactly two 48-byte assets");
    check(std::lower_bound(sorted.begin(), sorted.end(), std::size_t{50}, CompareBytes{})
              == upper, "insertion point for nonmatching byte count");

    // 265: Linear find is appropriate for unsorted names when building a
    // one-off snapshot; the live registry from M015 has a separate hash index.
    std::vector<std::string> names;
    names.reserve(assets.size());
    std::transform(assets.begin(), assets.end(), std::back_inserter(names),
                   [](const AssetRecord& a) { return a.name; });
    check(std::find(names.begin(), names.end(), "sky.tex") != names.end() &&
          std::find(names.begin(), names.end(), "absent") == names.end(),
          "linear find works without sorted input");

    // 266: transform is an elementwise expression here, not a guarantee of
    // parallel execution or SIMD. Preserve a numeric snapshot for reduction.
    std::vector<std::size_t> byte_sizes;
    byte_sizes.reserve(assets.size());
    std::transform(assets.begin(), assets.end(), std::back_inserter(byte_sizes),
                   [](const AssetRecord& a) { return a.bytes; });
    check(byte_sizes == std::vector<std::size_t>({48, 64, 16, 128, 48}),
          "transform projects each asset size");

    // 267-268: accumulate is an ordered left fold; reduce may regroup.
    // Unsigned sums are exact for these small values. Floating point requires
    // an explicit numerical-accuracy/reproducibility policy.
    const auto sequential_sum = std::accumulate(byte_sizes.begin(), byte_sizes.end(),
                                                std::size_t{0});
    const auto regroupable_sum = std::reduce(byte_sizes.begin(), byte_sizes.end(),
                                             std::size_t{0});
    check(sequential_sum == 304 && regroupable_sum == 304,
          "both integer reductions compute a small exact byte total");
    const double large = 1e20;
    const double a = ((large + 1.0) - large) + 3.0;
    const double b = (large - large) + (1.0 + 3.0);
    check(a == 3.0 && b == 4.0,
          "floating-point regrouping can change a result");

    // 269: remove_if rearranges the logical retained prefix; vector::erase
    // must destroy the obsolete suffix and actually reduce the size.
    std::vector<int> work_ids{1, 2, 3, 4, 5, 6};
    const auto retained_end = std::remove_if(work_ids.begin(), work_ids.end(),
                                            [](int id) { return id % 2 == 0; });
    check(std::distance(work_ids.begin(), retained_end) == 3 &&
          work_ids.size() == 6, "remove_if does not shrink vector");
    work_ids.erase(retained_end, work_ids.end());
    check(work_ids == std::vector<int>({1, 3, 5}),
          "erase/remove destroys the removed logical suffix");

    // 270: std::erase_if (C++20) expresses the combined operation directly.
    auto texture_removed = assets;
    const auto removed = std::erase_if(texture_removed,
        [](const AssetRecord& a) { return a.kind == AssetKind::Texture; });
    check(removed == 2 && texture_removed.size() == 3 &&
          std::all_of(texture_removed.begin(), texture_removed.end(),
            [](const AssetRecord& a) { return a.kind != AssetKind::Texture; }),
          "erase_if reports count and shrinks container");
    std::unordered_map<std::string, int> diagnostics{{"sky.tex", 3}, {"brick.mesh", 2}};
    const auto hash_removed = std::erase_if(diagnostics,
        [](const auto& key_and_priority) { return key_and_priority.second == 3; });
    check(hash_removed == 1 && diagnostics.size() == 1 &&
          diagnostics.contains("brick.mesh"),
          "C++20 erase_if works on appropriate associative containers");

    std::cout << "asset_query_algorithm_lab: all checks passed\n";
}
} // namespace allmight

int main() {
    try { allmight::run(); }
    catch (const std::exception& error) {
        std::cerr << "asset_query_algorithm_lab failed: " << error.what() << '\n';
        return 1;
    }
}

// Mathematics continuous-note C++20 first-contact oracle; code and tested source stay identical.
#include <cmath>
#include <iostream>
#include <optional>
#include <stdexcept>
struct Vec2 { double x{}, y{}; };
struct Disk2 { Vec2 centre{}, velocity{}; double radius{}; };
double dot(Vec2 a, Vec2 b) { return a.x*b.x+a.y*b.y; }

std::optional<double> firstTouch(Disk2 a, Disk2 b, double h) {
    const auto valid = [](Disk2 d) {
        return std::isfinite(d.centre.x)&&std::isfinite(d.centre.y)&&
               std::isfinite(d.velocity.x)&&std::isfinite(d.velocity.y)&&
               std::isfinite(d.radius)&&d.radius>0;
    };
    if (!valid(a)||!valid(b)||!std::isfinite(h)||h<0)
        throw std::invalid_argument("invalid disk or horizon");
    Vec2 p{b.centre.x-a.centre.x,b.centre.y-a.centre.y};
    Vec2 v{b.velocity.x-a.velocity.x,b.velocity.y-a.velocity.y};
    const double R=a.radius+b.radius;
    const double aa=dot(v,v),bb=2*dot(p,v),cc=dot(p,p)-R*R;
    if (!std::isfinite(aa)||!std::isfinite(bb)||!std::isfinite(cc))
        throw std::overflow_error("nonfinite collision coefficients");
    if (cc<0) throw std::domain_error("existing overlap");
    if (cc==0) return 0.0; // Touching, not automatically a new impact.
    if (aa==0||bb>=0) return std::nullopt;
    const double discriminant=std::fma(bb,bb,-4*aa*cc);
    if (!std::isfinite(discriminant))
        throw std::overflow_error("discriminant overflow");
    if (discriminant<0) return std::nullopt;
    const double q=-0.5*(bb-std::sqrt(discriminant));
    if (!(q>0)) return std::nullopt;
    const double t=cc/q;
    if (!std::isfinite(t)||t<0||t>h) return std::nullopt;
    return t;
}
int main() {
    auto near=[](double actual,double expected) {
        if (!std::isfinite(actual)||std::abs(actual-expected)>1e-10)
            throw std::runtime_error("unexpected first-contact time");
    };
    const Disk2 fixed{{0,0},{0,0},1};
    const Disk2 moving{{10,0},{-100,0},1};
    const auto impact=firstTouch(fixed,moving,0.1);
    if (!impact) throw std::runtime_error("fast contact was missed");
    near(*impact,0.08);
    if (firstTouch(fixed,moving,0.05))
        throw std::runtime_error("collision outside horizon was accepted");
    if (firstTouch(fixed,{{10,0},{100,0},1},1.0))
        throw std::runtime_error("separating disks reported impact");
    if (firstTouch(fixed,{{10,0},{0,0},1},1.0))
        throw std::runtime_error("static separated disks reported impact");
    if (firstTouch(fixed,{{10,2.1},{-10,0},1},2.0))
        throw std::runtime_error("geometric near miss reported impact");
    const auto tangent=firstTouch(fixed,{{10,2},{-10,0},1},2.0);
    if (!tangent) throw std::runtime_error("tangency not found");
    near(*tangent,1.0);
    const auto galilean=firstTouch({{0,0},{55,7},1},
                                   {{10,0},{-45,7},1},0.1);
    if (!galilean) throw std::runtime_error("relative motion invariance failed");
    near(*galilean,0.08);
    bool rejected=false;
    try { (void)firstTouch(fixed,{{1,0},{0,0},1},1); }
    catch(const std::domain_error&) { rejected=true; }
    if (!rejected) throw std::runtime_error("initial overlap not rejected");
    rejected=false;
    try { (void)firstTouch(fixed,moving,-1); }
    catch(const std::invalid_argument&) { rejected=true; }
    if (!rejected) throw std::runtime_error("negative time accepted");
    std::cout<<"math first contact: entry, no-hit, tangency, invariance and validation PASS\n";
}

// Project AllMight M015 / Parts 231-250.
// C++20 standalone laboratory: a growing asset registry, borrowed views,
// container invalidation, hash collisions, and scheduling adapters.
// This models CPU-side ownership. No GPU queue or native asset source is used.
#include <algorithm>
#include <array>
#include <cassert>
#include <cstddef>
#include <cstdint>
#include <deque>
#include <forward_list>
#include <functional>
#include <iostream>
#include <limits>
#include <iterator>
#include <memory>
#include <list>
#include <map>
#include <optional>
#include <queue>
#include <set>
#include <span>
#include <stack>
#include <stdexcept>
#include <string>
#include <string_view>
#include <type_traits>
#include <unordered_map>
#include <unordered_set>
#include <utility>
#include <vector>

namespace allmight {
void verify(bool ok, const char* explanation) {
    if (!ok) throw std::runtime_error(explanation); // checks survive NDEBUG
}

struct Asset {
    std::string name;                     // owns its characters
    std::vector<std::uint8_t> source;     // owns its bytes
};

// Keep identity independent of where a std::vector element happens to live.
// Reusing an old slot changes its generation, so stale handles are rejected.
struct AssetHandle {
    std::size_t slot;
    std::uint64_t generation;
    friend bool operator==(const AssetHandle&, const AssetHandle&) = default;
};

class AssetRegistry {
    struct Slot {
        std::optional<Asset> value;
        std::uint64_t generation = 1;
    };
    std::vector<Slot> slots_;
    std::vector<std::size_t> free_;
    std::unordered_map<std::string, AssetHandle> names_;

public:
    std::size_t slot_count() const noexcept { return slots_.size(); }
    std::size_t size() const noexcept { return names_.size(); }
    std::size_t capacity() const noexcept { return slots_.capacity(); }

    // Single-threaded transaction: a new slot is published to the name index
    // only after the owning Asset is complete. Roll back a slot if the hash
    // insertion throws; existing handles and values remain unchanged.
    AssetHandle insert(std::string name, std::vector<std::uint8_t> source,
                       bool fail_preparation = false, bool fail_commit = false) {
        if (name.empty() || source.empty())
            throw std::invalid_argument("asset name/data cannot be empty");
        if (names_.contains(name))
            throw std::invalid_argument("duplicate asset name");
        if (fail_preparation)
            throw std::runtime_error("simulated failure before publication");

        static_assert(std::is_nothrow_move_constructible_v<Asset>);
        // When a slot is reused, its already-incremented generation identifies
        // the NEW occupant, not the previous object once held at that index.
        const bool reuse = !free_.empty();
        const std::size_t index = reuse ? free_.back() : slots_.size();
        if (!reuse) slots_.emplace_back();
        Slot& slot = slots_[index];
        slot.value.emplace(Asset{std::move(name), std::move(source)});
        const AssetHandle handle{index, slot.generation};
        try {
            // Deliberately fail after constructing the slot but before its
            // name becomes externally discoverable, then verify rollback.
            if (fail_commit) throw std::runtime_error("injected commit failure");
            const auto [it, published] = names_.emplace(slot.value->name, handle);
            (void)it;
            if (!published) throw std::logic_error("duplicate during commit");
        } catch (...) {
            slot.value.reset(); // release the uncommitted owning payload
            if (!reuse) slots_.pop_back();
            throw;
        }
        if (reuse) free_.pop_back();
        return handle;
    }

    const Asset* resolve(AssetHandle h) const noexcept {
        if (h.slot >= slots_.size()) return nullptr;
        const Slot& slot = slots_[h.slot];
        if (slot.generation != h.generation || !slot.value) return nullptr;
        return std::addressof(*slot.value);
    }
    std::optional<AssetHandle> find(std::string_view name) const {
        // The temporary owns the queried characters during this lookup.
        // A production transparent hasher could avoid this allocation.
        auto it = names_.find(std::string(name));
        if (it == names_.end()) return std::nullopt;
        return it->second;
    }
    bool erase(AssetHandle h) {
        const Asset* found = resolve(h);
        if (!found) return false;
        if (slots_[h.slot].generation == std::numeric_limits<std::uint64_t>::max())
            throw std::overflow_error("generation exhausted; cannot reuse slot");
        // Reserving free-list capacity happens before mutations, so failure
        // here does not remove the published asset.
        free_.reserve(free_.size() + 1);
        names_.erase(found->name);
        Slot& slot = slots_[h.slot];
        slot.value.reset(); // destroys the stored name and byte vector
        ++slot.generation;
        free_.push_back(h.slot);
        return true;
    }
};

struct ConstantHash {
    std::size_t operator()(const std::string&) const noexcept { return 0; }
};

struct UploadJob { int priority; std::uint64_t sequence; std::string name; };
struct JobLess {
    bool operator()(const UploadJob& left, const UploadJob& right) const {
        if (left.priority != right.priority) return left.priority < right.priority;
        // Earlier sequence wins ties; priority_queue is not inherently stable.
        return left.sequence > right.sequence;
    }
};

std::size_t checksum(std::span<const std::uint8_t> bytes) noexcept {
    std::size_t sum = 0;
    for (std::uint8_t byte : bytes) sum += byte;
    return sum;
}

void run() {
    // vector: size means live elements, capacity means available storage.
    std::vector<int> dense;
    dense.reserve(2);
    verify(dense.size() == 0 && dense.capacity() >= 2, "reserve does not create elements");
    dense.push_back(10);
    dense.push_back(20);
    const std::size_t capacity_before = dense.capacity();
    // At this point a pointer/span into dense could be retained only if no
    // invalidating operation follows. We intentionally retain NO such pointer.
    dense.push_back(30); // guaranteed to reallocate when size == capacity
    const std::size_t capacity_after_growth = dense.capacity();
    verify(capacity_after_growth > capacity_before && dense.size() == 3,
           "growth requires new capacity; old iterators would be invalid");
    dense.resize(5); // constructs two live zero-initialized int elements
    verify(dense.size() == 5 && dense[3] == 0 && dense[4] == 0,
           "resize changes size, not merely reserved storage");
    std::cout << "vector capacity growth: " << capacity_before << " -> "
              << capacity_after_growth << "\n";

    // array stays fixed and contiguous. deque permits cheap front/back work,
    // but is not itself one contiguous T[N] allocation and has distinct rules.
    std::array<int, 3> fixed{2, 4, 6};
    verify(checksum(std::span<const std::uint8_t>{}) == 0, "empty span is valid");
    verify(fixed.size() == 3 && fixed.data()[2] == 6, "fixed array contiguous");
    std::deque<int> ends;
    ends.push_back(2);
    ends.push_front(1);
    ends.push_back(3);
    verify(ends.front() == 1 && ends.back() == 3 && ends[1] == 2,
           "deque indexed segmented sequence");

    // Linked containers keep node iterators/references stable under splicing,
    // subject to the operations' normal preconditions and erasure rules.
    std::list<std::string> edits{"import", "compile"};
    auto compile_it = std::next(edits.begin());
    std::list<std::string> incoming{"upload"};
    edits.splice(edits.end(), incoming, incoming.begin());
    verify(*compile_it == "compile" && incoming.empty() && edits.back() == "upload",
           "list node transfer preserves unrelated iterators");
    std::forward_list<int> singly{1, 2, 3};
    singly.erase_after(singly.begin()); // removes 2, not 1
    verify(std::vector<int>(singly.begin(), singly.end()) == std::vector<int>({1, 3}),
           "forward_list erase_after needs predecessor");

    // Ordered maps/sets use comparison order and logarithmic operations.
    std::map<std::string, int> named{{"mesh", 1}, {"shader", 3}, {"texture", 2}};
    std::set<int> unique_ids{8, 3, 8, 5};
    verify(named.begin()->first == "mesh" && unique_ids.size() == 3 &&
               *unique_ids.begin() == 3, "ordered unique-key containers");

    // Unordered containers are lookup-oriented. Hash equality MUST be
    // consistent with key equality. A pathological constant hash preserves
    // correctness, but forces the keys into one bucket.
    std::unordered_map<std::string, int, ConstantHash> collisions;
    collisions.max_load_factor(0.5f);
    for (int i = 0; i < 24; ++i) collisions.emplace("asset" + std::to_string(i), i);
    verify(collisions.size() == 24 && collisions.at("asset19") == 19,
           "collisions do not change key equality or lookup results");
    const auto bucket = collisions.bucket("asset0");
    verify(collisions.bucket_size(bucket) == collisions.size(),
           "constant hasher sends every key to one bucket");
    const auto buckets_before = collisions.bucket_count();
    collisions.reserve(96); // at max_load_factor 0.5, requests enough buckets
    verify(collisions.bucket_count() >= buckets_before &&
               collisions.load_factor() <= collisions.max_load_factor(),
           "rehash policy and load factor contract");
    // Do not dereference any pre-rehash iterator: rehash invalidates iterators.
    std::unordered_set<std::string> pending{"mesh", "texture", "mesh"};
    verify(pending.size() == 2 && pending.contains("texture"),
           "unordered_set expresses membership without a value field");

    // Adapters expose scheduling semantics, not iteration/layout guarantees.
    std::priority_queue<UploadJob, std::vector<UploadJob>, JobLess> priority;
    priority.push({3, 2, "later-high"});
    priority.push({1, 3, "low"});
    priority.push({3, 1, "earlier-high"});
    verify(priority.top().name == "earlier-high", "priority and tie break");
    priority.pop();
    verify(priority.top().name == "later-high", "heap next highest job");
    std::queue<int> arrivals;
    arrivals.push(7); arrivals.push(8);
    verify(arrivals.front() == 7, "queue FIFO"); arrivals.pop();
    verify(arrivals.front() == 8, "queue second arrival");
    std::stack<int> undo;
    undo.push(7); undo.push(8);
    verify(undo.top() == 8, "stack LIFO"); undo.pop();
    verify(undo.top() == 7, "stack previous entry");

    AssetRegistry registry;
    const AssetHandle first = registry.insert("rocks.mesh", {10, 20, 30});
    verify(registry.resolve(first) && registry.size() == 1,
           "asset is published at stable logical handle");
    verify(checksum(registry.resolve(first)->source) == 60,
           "span-like read over stored contiguous bytes");
    const auto found = registry.find("rocks.mesh");
    verify(found && *found == first, "owned name index returns logical handle");
    const std::size_t old_slots = registry.slot_count();
    bool failed = false;
    try { (void)registry.insert("broken.mesh", {1, 2, 3}, true); }
    catch (const std::runtime_error&) { failed = true; }
    verify(failed && registry.size() == 1 && registry.slot_count() == old_slots,
           "injected pre-publication error does not mutate registry");
    bool commit_failed = false;
    try { (void)registry.insert("commit-broken.mesh", {9, 9}, false, true); }
    catch (const std::runtime_error&) { commit_failed = true; }
    verify(commit_failed && registry.size() == 1 &&
               registry.slot_count() == old_slots && registry.resolve(first),
           "failed publication rolls back the unpublished slot");
    verify(registry.erase(first) && !registry.resolve(first),
           "old generation cannot resolve after erase");
    const AssetHandle second = registry.insert("fresh.mesh", {1, 2});
    verify(second.slot == first.slot && second.generation != first.generation &&
               !registry.resolve(first) && registry.resolve(second),
           "reused slot has a new generation and old handle remains stale");

    // string_view is a borrowed (pointer,length) view and may contain no NUL.
    // Copy to std::string when a name must survive the temporary source.
    std::string owner = "texture/stone/normal.png";
    std::string_view name_view{owner};
    const auto subpath = name_view.substr(8, 5); // "stone", not NUL terminated
    verify(subpath == "stone" && subpath.size() == 5, "view knows its length");
    const std::string owned_name{subpath};
    owner.clear(); // invalidates borrowed content; do not use subpath afterward
    verify(owned_name == "stone", "copied string survives source mutation");
    std::string short_text = "mesh";
    std::string long_text(1000, 'x');
    verify(short_text.size() == 4 && long_text.size() == 1000,
           "strings own content whether or not implementation uses SSO");
    std::cout << "string capacities (short/long): " << short_text.capacity()
              << '/' << long_text.capacity() << " (implementation-dependent)\n";
    std::cout << "asset_container_lab: all checks passed\n";
}
